// Remembers when each job last checked in. Called by GET /webhook/heartbeat?name=<job>
const mem = $getWorkflowStaticData('global');
mem.last = mem.last || {};
const out = [];
for (const item of $input.all()) {
  const name = String((item.json.query || {}).name || '').trim().slice(0, 64);
  if (!name) { out.push({ json: { ok: false, error: 'add ?name=<job> to the URL' } }); continue; }
  mem.last[name] = Date.now();
  out.push({ json: { ok: true, name, at: new Date().toISOString() } });
}
return out;

// One line per job: name (same as ?name=...) and how many minutes it may stay quiet.
const HEARTBEATS = [
  { name: 'nightly-backup', maxMinutes: 26 * 60 },
  { name: 'price-scraper',  maxMinutes: 120 },
];
const mem = $getWorkflowStaticData('global');
mem.last = mem.last || {}; mem.down = mem.down || {};
if (!mem.since) mem.since = Date.now(); // jobs never seen get a grace period from first activation
const now = Date.now(), lines = [];
for (const hb of HEARTBEATS) {
  const seen = mem.last[hb.name];
  const age = (now - (seen || mem.since)) / 60000;
  const late = age > hb.maxMinutes;
  const when = seen ? `${Math.round(age)} min ago` : 'never';
  if (late && !mem.down[hb.name]) { mem.down[hb.name] = true; lines.push(`🔴 ${hb.name}: no heartbeat for ${hb.maxMinutes} min (last: ${when})`); }
  if (!late && mem.down[hb.name]) { delete mem.down[hb.name]; lines.push(`🟢 ${hb.name} is back (last: ${when})`); }
}
if (!lines.length) return []; // nothing changed: stop here, no alert
return [{ json: { content: ('Heartbeat watchdog\n' + lines.join('\n')).slice(0, 1990) } }];
